    description: "チャンネルストリップは、マイクプリ、EQ、コンプレッサーなど、1本の音に対してよく使う処理を1台（または1つのプラグイン）にまとめたものです。コンソールの「1本のチャンネル」を箱に切り出した、と説明されることもあります。\n\n実機の典型的な流れは、マイク → チャンネルストリップ → オーディオインターフェース（LINE IN）→ DAW です。ストリップの中で増幅し、EQやコンプで色をつけてから、すでに大きなラインレベルの信号としてIFへ入れます。IF内蔵マイクプリを使わず、ストリップ側のマイクプリを使う、という使い方です。\n\nこれを使うと、録音前の音作りを1か所で行いやすくなります。プロのスタジオではよく使われます。プラグイン版は宅録のDAWでもよく使い、Neutron や Nectar のような「1トラックの整え」も近い考え方です。\n\n一般的な宅録では必須ではありません。DAWのEQとコンプを別々に挿しても、あとから似た処理はできます。実機を足すのは、録音段階からキャラクターを決めたいときや、コンソール的な流れを手元に置きたいときです。そのためにはIFにライン入力があることが重要です。\n\nRupert Neve Designs Shelford Channel がこの種類として登録されていますが、所有ではなく購入検討です。今の所有環境では、MOTU M2 / UR242 の内蔵マイクプリと、DAW側のEQ・コンプで同じ役割を分けて担っています。",
    doesWhat: "1チャンネル分の音作りをまとめて行う。代表的には、マイクプリ ＋ EQ ＋ コンプレッサーなど。",
